try:
  ta_safe_ma
  ta_safe_std
  ta_safe_rsi
  ta_safe_stoch_rsi
except NameError:
  def _tc_effective_period(length, available_count):
    try:
      requested = int(float(length if length is not None else 1))
    except (TypeError, ValueError):
      requested = 1
    return max(1, min(max(1, requested), max(1, int(available_count or 0))))

  def ta_safe_rma(series, length):
    values = pd.Series(series, dtype="float64")
    period = _tc_effective_period(length, len(values))
    return values.ewm(alpha=1.0 / period, adjust=False, min_periods=1).mean()

  def ta_safe_wma(series, length):
    values = pd.Series(series, dtype="float64")
    period = _tc_effective_period(length, len(values))

    def _tc_weighted_average(window_values):
      if len(window_values) == 0:
        return np.nan
      weights = np.arange(1, len(window_values) + 1, dtype="float64")
      return float(np.dot(window_values, weights) / weights.sum())

    return values.rolling(window=period, min_periods=1).apply(_tc_weighted_average, raw=True)

  def ta_safe_vwma(series, volume, length):
    values = pd.Series(series, dtype="float64")
    volume_values = pd.Series(volume, dtype="float64").reindex(values.index).fillna(0.0)
    period = _tc_effective_period(length, len(values))
    numerator = (values * volume_values).rolling(window=period, min_periods=1).sum()
    denominator = volume_values.rolling(window=period, min_periods=1).sum().replace(0.0, np.nan)
    fallback = values.rolling(window=period, min_periods=1).mean()
    return (numerator / denominator).replace([np.inf, -np.inf], np.nan).fillna(fallback)

  def ta_safe_ma(series, length, ma_type="SMA", volume=None):
    values = pd.Series(series, dtype="float64")
    period = _tc_effective_period(length, len(values))
    normalized = str(ma_type or "SMA").strip().upper()
    if normalized == "EMA":
      return values.ewm(span=period, adjust=False, min_periods=1).mean()
    if normalized in {"SMMA (RMA)", "RMA", "SMMA"}:
      return ta_safe_rma(values, period)
    if normalized == "WMA":
      return ta_safe_wma(values, period)
    if normalized == "VWMA":
      return ta_safe_vwma(values, values if volume is None else volume, period)
    return values.rolling(window=period, min_periods=1).mean()

  def ta_safe_std(series, length, multiplier=1.0):
    values = pd.Series(series, dtype="float64")
    period = _tc_effective_period(length, len(values))
    return values.rolling(window=period, min_periods=1).std(ddof=0).fillna(0.0) * float(multiplier)

  def ta_safe_rsi(series, length):
    values = pd.Series(series, dtype="float64")
    period = _tc_effective_period(length, len(values))
    change = values.diff().fillna(0.0)
    up = pd.Series(np.where(change > 0, change, 0.0), index=values.index, dtype="float64")
    down = pd.Series(np.where(change < 0, -change, 0.0), index=values.index, dtype="float64")
    up_rma = ta_safe_rma(up, period)
    down_rma = ta_safe_rma(down, period)
    rs = up_rma / down_rma.replace(0.0, np.nan)
    result = 100.0 - (100.0 / (1.0 + rs))
    flat = (up_rma == 0) & (down_rma == 0)
    result = result.mask((down_rma == 0) & ~flat, 100.0)
    result = result.mask((up_rma == 0) & (down_rma > 0), 0.0)
    result = result.mask(flat, 50.0)
    return result.replace([np.inf, -np.inf], np.nan).fillna(50.0)

  def ta_safe_stoch_rsi(series, rsi_length, stoch_length, smooth_k=3, smooth_d=3):
    rsi_values = ta_safe_rsi(series, rsi_length)
    stoch_period = _tc_effective_period(stoch_length, len(rsi_values))
    lowest = rsi_values.rolling(window=stoch_period, min_periods=1).min()
    highest = rsi_values.rolling(window=stoch_period, min_periods=1).max()
    range_values = (highest - lowest).replace(0.0, np.nan)
    stoch = ((rsi_values - lowest) / range_values * 100.0).replace([np.inf, -np.inf], np.nan).fillna(50.0)
    k = ta_safe_ma(stoch, smooth_k, "SMA")
    d = ta_safe_ma(k, smooth_d, "SMA")
    return stoch, k, d

