  def ta_safe_rsi(series, length):
    values = pd.Series(series, dtype="float64")
    period = _tc_effective_period(length, len(values))
    change = values.diff().fillna(0.0)
    up = pd.Series(np.where(change > 0, change, 0.0), index=values.index, dtype="float64")
    down = pd.Series(np.where(change < 0, -change, 0.0), index=values.index, dtype="float64")
    up_rma = ta_safe_rma(up, period)
    down_rma = ta_safe_rma(down, period)
    rs = up_rma / down_rma.replace(0.0, np.nan)
    result = 100.0 - (100.0 / (1.0 + rs))
    flat = (up_rma == 0) & (down_rma == 0)
    result = result.mask((down_rma == 0) & ~flat, 100.0)
    result = result.mask((up_rma == 0) & (down_rma > 0), 0.0)
    result = result.mask(flat, 50.0)
    return result.replace([np.inf, -np.inf], np.nan).fillna(50.0)

  def ta_safe_stoch_rsi(series, rsi_length, stoch_length, smooth_k=3, smooth_d=3):
    rsi_values = ta_safe_rsi(series, rsi_length)
    stoch_period = _tc_effective_period(stoch_length, len(rsi_values))
    lowest = rsi_values.rolling(window=stoch_period, min_periods=1).min()
    highest = rsi_values.rolling(window=stoch_period, min_periods=1).max()
    range_values = (highest - lowest).replace(0.0, np.nan)
    stoch = ((rsi_values - lowest) / range_values * 100.0).replace([np.inf, -np.inf], np.nan).fillna(50.0)
    k = ta_safe_ma(stoch, smooth_k, "SMA")
    d = ta_safe_ma(k, smooth_d, "SMA")
    return stoch, k, d

